data: {"id": "22aca728-fdf5-4f32-842e-d4b0e4f1b15e:directions", "type": "directions", "options": [{"id": "direction-1", "name": "午后窗畔慢时光", "scene": "咖啡店靠窗的木桌位，窗外有轻微秋日梧桐影，桌上一杯拿铁和翻开的书", "mood": "安静、温柔、松弛带点文艺", "palette": ["米白", "浅蓝", "浅木色", "暖阳光"], "why": "窗边侧光最容易把亚麻的肌理和米白的柔和拍出来，浅蓝牛仔在暖光里显得清爽不冷；三张可以分别是窗边半身、袖口自然搭在桌沿的近景、起身离开的全身，节奏完整", "sample_title": "秋日窗边，米白亚麻的松弛感", "preview_status": "queued", "preview_url": null}, {"id": "direction-2", "name": "街角外摆的随性一刻", "scene": "咖啡店门口的小圆桌外摆，背后是玻璃门和绿植，路过的人流虚化", "mood": "轻快、生活化、像顺路坐下喝一杯", "palette": ["米白", "浅蓝", "深绿", "灰砖"], "why": "室外自然光让宽松版型更明显，牛仔裤的直筒高腰轮廓能完整展示；袖口卷起的细节可以在抬手拨头发或拿杯子的动作里自然看清", "sample_title": "楼下咖啡店，随便坐一下", "preview_status": "queued", "preview_url": null}, {"id": "direction-3", "name": "吧台边的日常细节", "scene": "咖啡店吧台旁的窄桌，背景是咖啡机器和木质杯架，人物靠在高脚椅边", "mood": "低调、有质感、日常氛围感", "palette": ["米白", "浅蓝", "深木褐", "哑光金属"], "why": "偏暗的环境能把米白衬衫提亮成画面焦点，适合放胸前口袋和纽扣前襟的特写；三张按封面半身、袖口纽扣特写、吧台前全身来排，细节交代最集中", "sample_title": "咖啡店吧台，米白衬衫的一天", "preview_status": "queued", "preview_url": null}]}

