data: {"id": "22aca728-fdf5-4f32-842e-d4b0e4f1b15e:script", "type": "script", "status": "draft", "title_ideas": ["秋日窗边，米白亚麻的松弛感", "咖啡店靠窗，穿一身米白配浅蓝", "亚麻衬衫的午后，慢慢喝一杯"], "cover": {"scene": "咖啡店靠窗木桌位，窗外秋日梧桐影落在桌面，一杯拿铁和翻开的书在旁", "pose": "侧身半坐，手肘轻搭桌沿，身体略向窗光，视线看向窗外", "text_overlay": "秋日窗边的米白亚麻"}, "shots": [{"id": "shot-1", "scene": "咖啡店靠窗木桌位，暖阳光斜进来，桌上有拿铁和翻开的书", "outfit_asset_ids": ["bc75d622-106b-4d12-bdb7-9d1232689a89", "7d6612d1-bb61-4d57-9f10-c11ccbfae12e"], "pose": "半身侧坐，手肘搭桌沿，另一手轻扶杯身", "camera": "半身中景，平视略偏侧，暖光侧逆", "caption": "窗边坐下，米白亚麻的柔软和浅蓝牛仔的清透刚好搭在一起"}, {"id": "shot-2", "scene": "同一张木桌，窗光落在桌沿，拿铁和书在画面边缘", "outfit_asset_ids": ["bc75d622-106b-4d12-bdb7-9d1232689a89"], "pose": "小臂自然搭在桌沿，袖子轻微卷起，手腕放松露出袖口翻边", "camera": "近距离特写，俯拍带一点斜角，焦点在袖口与胸前口袋", "caption": "袖子随便卷两下，亚麻的纹理和胸前口袋在近景里最清楚"}, {"id": "shot-3", "scene": "咖啡店门口内侧，起身离开，背后是玻璃门和窗外梧桐影", "outfit_asset_ids": ["bc75d622-106b-4d12-bdb7-9d1232689a89", "7d6612d1-bb61-4d57-9f10-c11ccbfae12e"], "pose": "自然站姿，一手拿书，微微回头", "camera": "全身竖构图，略低机位，自然光", "caption": "站起来看全身，宽松衬衫配高腰直筒牛仔，比例很清爽"}], "video": {"prompt": "秋日午后咖啡店靠窗木桌，同一位博主穿米白亚麻短袖衬衫和浅蓝高腰直筒牛仔裤，侧身坐在窗边，手肘轻搭桌沿，端起拿铁轻抿，窗光缓慢移动，发丝和衣摆自然微动，镜头轻微前推，安静松弛的氛围，5 秒", "duration": 5}, "version": 1}

event: done
